<!doctype html>
<html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>登录方式</title><link rel="stylesheet" href="/assets/css/style.css"><style>.oauth-page{min-height:100vh;padding:18px 16px 110px;background:var(--bg-main,#f6f8fb)}.oauth-shell{max-width:760px;margin:0 auto}.oauth-head{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:14px}.oauth-title{font-size:24px;font-weight:950;color:var(--text-main,#0f172a)}.oauth-list{display:grid;gap:10px}.oauth-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 16px;border:1px solid var(--line-soft,#e2e8f0);border-radius:18px;background:var(--card-bg,#fff);box-shadow:0 8px 24px rgba(15,23,42,.04)}.oauth-name{font-weight:950}.oauth-desc{font-size:12px;color:var(--text-soft,#64748b);margin-top:3px}.oauth-actions{display:flex;gap:8px;align-items:center}.oauth-actions .btn{height:30px!important;padding:0 10px!important;border-radius:999px!important;font-size:12px!important}.alert{padding:10px 12px;border-radius:14px;margin-bottom:12px;font-size:13px}.alert.ok{background:#dcfce7;color:#15803d}.alert.err{background:#fef2f2;color:#b91c1c}@media(max-width:640px){.oauth-head,.oauth-row{align-items:flex-start}.oauth-row{display:grid}.oauth-page{padding:14px 12px 104px}}</style></head><body><?php require __DIR__ . '/../layouts/topbar.php'; ?><main class="oauth-page"><div class="oauth-shell"><div class="oauth-head"><div><div class="oauth-title">登录方式</div><div class="oauth-desc">绑定 QQ、GitHub、微信或彩虹聚合登录。绑定任意一种即可完成对应成长任务。</div></div><a class="btn btn-light" style="text-decoration:none;" href="/index.php?path=settings">返回设置</a></div><?php if($success): ?><div class="alert ok"><?= htmlspecialchars($success) ?></div><?php endif; ?><?php if($error): ?><div class="alert err"><?= htmlspecialchars($error) ?></div><?php endif; ?><div class="oauth-list"><?php foreach($providers as $key=>$provider): ?><?php $bound=$bindings[$key]??null; ?><div class="oauth-row"><div><div class="oauth-name"><?= htmlspecialchars($provider['name']) ?></div><div class="oauth-desc"><?php if($bound): ?>已绑定：<?= htmlspecialchars((string)($bound['nickname'] ?: $bound['openid'])) ?><?php elseif(empty($provider['enabled'])): ?>未开启<?php else: ?>未绑定<?php endif; ?></div></div><div class="oauth-actions"><?php if($bound): ?><form method="post" action="/index.php?path=oauth/unbind" onsubmit="return confirm('确认解绑该登录方式？')"><?= csrf_field() ?><input type="hidden" name="provider" value="<?= htmlspecialchars($key) ?>"><button class="btn btn-light" type="submit">解绑</button></form><?php elseif(!empty($provider['enabled'])): ?><a class="btn" style="text-decoration:none;" href="/index.php?path=oauth/redirect&provider=<?= urlencode($key) ?>">绑定</a><?php else: ?><span class="oauth-desc">不可用</span><?php endif; ?></div></div><?php endforeach; ?></div></div></main><?php require dirname(__DIR__, 2) . '/layouts/theme-toggle.php'; ?><?php require __DIR__ . '/../layouts/bottom-nav.php'; ?></body></html>
